### 2️⃣ Tests Unitarios: `tests/MathUtilsTest.php`
```php
<?php

declare(strict_types=1);

namespace Tests;

use PHPUnit\Framework\TestCase;
use App\MathUtils;
use InvalidArgumentException;

class MathUtilsTest extends TestCase
{
    public function testFactorialDeCero(): void
    {
        $this->assertSame(1, MathUtils::factorial(0));
    }

    public function testFactorialDeUno(): void
    {
        $this->assertSame(1, MathUtils::factorial(1));
    }

    public function testFactorialDeCinco(): void
    {
        $this->assertSame(120, MathUtils::factorial(5));
    }

    public function testFactorialDeDiez(): void
    {
        $this->assertSame(3628800, MathUtils::factorial(10));
    }

    public function testLanzaExcepcionParaNumerosNegativos(): void
    {
        $this->expectException(InvalidArgumentException::class);
        $this->expectExceptionMessage('El factorial no está definido para números negativos.');

        MathUtils::factorial(-5);
    }

    // PHPUnit valida automáticamente el tipado gracias a declare(strict_types=1) y las type hints.
    // Este test es opcional pero demuestra que se respeta el contrato de tipos.
    public function testRechazaTiposNoEnteros(): void
    {
        $this->expectException(\TypeError::class);
        MathUtils::factorial(5.5);
    }
}
```

