Aquí tienes un snippet moderno, seguro y listo para producción:

```php
<?php

/**
 * Ejecuta una consulta SELECT con parámetros seguros y devuelve los resultados como array asociativo.
 *
 * @param string $host     Host de la base de datos
 * @param string $database Nombre de la base de datos
 * @param string $usuario  Usuario de conexión
 * @param string $password Contraseña de conexión
 * @param string $sql      Consulta SQL con marcadores ? o :nombre
 * @param array  $params   Array con los valores para vincular a los marcadores
 * @return array           Resultados como arrays asociativos
 */
function ejecutarConsultaSelect(string $host, string $database, string $usuario, string $password, string $sql, array $params = []): array {
    // Configuración segura del DSN y opciones PDO
    $dsn = "mysql:host=$host;dbname=$database;charset=utf8mb4";
    $options = [
        PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION, // Activa el manejo por excepciones
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,       // Devuelve filas como arrays asociativos por defecto
        PDO::ATTR_EMULATE_PREPARES   => false,                  // Usa prepared statements nativos (más seguro en MySQL)
        PDO::ATTR_PERSISTENT         => false,                  // Evita conexiones persistentes no necesarias
    ];

    try {
        // 1. Establecer conexión
        $pdo = new PDO($dsn, $usuario, $password, $options);

        // 2. Preparar la consulta (protege contra inyección SQL)
        $stmt = $pdo->prepare($sql);

        // 3. Ejecutar con parámetros vinculados de forma segura
        $stmt->execute($params);

        // 4. Obtener todos los resultados como array asociativo
        return $stmt->fetchAll();

    } catch (PDOException $e) {
        // Manejo centralizado de errores de base de datos
        error_log("PDO Error: " . $e->getMessage());

        // En producción, se recomienda lanzar una excepción genérica para no filtrar detalles internos
        throw new RuntimeException("Error al ejecutar la consulta. Intente más tarde.", (int)$e->getCode(), $e);
    }
}

// ==========================================
// EJEMPLO DE USO
// ==========================================
